import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import {Button, Details, Stack, useDetails} from '@primer/react'

import styles from './AlertMetadataDetails.module.css'

export const AlertMetadataDetails = ({summary, children}: {summary: React.ReactNode; children: React.ReactNode}) => {
  const {getDetailsProps} = useDetails({})
  const detailsProps = getDetailsProps()
  const leadingVisual = detailsProps.open ? ChevronDownIcon : ChevronRightIcon

  return (
    <Details className={`rounded-2 ${styles.AlertMetadataDetails}`} {...detailsProps}>
      <Button
        block
        as="summary"
        size="small"
        variant="invisible"
        alignContent="start"
        className="tmp-pl-1 tmp-py-3"
        leadingVisual={leadingVisual}
      >
        {summary}
      </Button>

      <Stack gap="condensed" className="tmp-pl-4 tmp-pr-2 tmp-pb-2">
        {children}
      </Stack>
    </Details>
  )
}
