import {Spinner, Stack} from '@primer/react'
import {AlertMetadataDetails} from '@github-ui/platform-patterns/AlertPageSidebar'
import {IncludeFragment} from '@github-ui/include-fragment-react'
import {cweFragmentPath} from '@github-ui/paths'

export type CWEItemProps = {
  cweNumber: number
}

export function CWEItem({cweNumber}: CWEItemProps) {
  return (
    <AlertMetadataDetails
      summary={
        <>
          <span className="sr-only">Weakness</span> CWE-{cweNumber}
        </>
      }
    >
      <IncludeFragment src={cweFragmentPath({id: cweNumber.toString()})} loading="lazy">
        <Stack align="center" direction="horizontal" data-hide-on-error>
          <Spinner size="small" />
          <span>Loading CWE…</span>
        </Stack>
        <span className="text-italic" data-show-on-error hidden>
          Error fetching details for CWE-{cweNumber}.
        </span>
      </IncludeFragment>
    </AlertMetadataDetails>
  )
}
