import type {ReactNode} from 'react'
import {Dialog, useFocusZone, type DialogButtonProps} from '@primer/react'
import {FocusKeys} from '@primer/behaviors'

import styles from './DeleteConfigurationDialogFooter.module.css'

export type DeleteConfigurationDialogFooterProps = {
  footerText?: ReactNode
  footerButtons: DialogButtonProps[]
}

export function DeleteConfigurationDialogFooter({footerText, footerButtons}: DeleteConfigurationDialogFooterProps) {
  const {containerRef: footerRef} = useFocusZone({
    bindKeys: FocusKeys.ArrowHorizontal | FocusKeys.Tab,
    focusInStrategy: 'closest',
  })
  return (
    <Dialog.Footer ref={footerRef as React.RefObject<HTMLDivElement>} className={styles.root}>
      {footerText ? <div className={styles.text}>{footerText}</div> : null}
      <Dialog.Buttons buttons={footerButtons} />
    </Dialog.Footer>
  )
}
