import type {AgenticAutofixError} from '@github-ui/code-scanning-shared/types/agentic-autofix-error'
import {ssrSafeDocument} from '@github-ui/ssr-utils'

export const AGENTIC_AUTOFIX_STARTED_EVENT_NAME = 'code-scanning-alert-agentic-autofix-started'

export type AgenticAutofixJob = {
  jobId: string
}

export type AgenticAutofixStartedEvent = CustomEvent<AgenticAutofixJob>

export function dispatchAgenticAutofixStarted(job: AgenticAutofixJob) {
  ssrSafeDocument?.dispatchEvent(new CustomEvent(AGENTIC_AUTOFIX_STARTED_EVENT_NAME, {detail: job}))
}

export function onAgenticAutofixStarted(callback: (job: AgenticAutofixJob) => void) {
  const handler = (event: Event) => callback((event as AgenticAutofixStartedEvent).detail)
  ssrSafeDocument?.addEventListener(AGENTIC_AUTOFIX_STARTED_EVENT_NAME, handler)
  return () => ssrSafeDocument?.removeEventListener(AGENTIC_AUTOFIX_STARTED_EVENT_NAME, handler)
}

export type AgenticAutofixErrorEvent = CustomEvent<AgenticAutofixError>

export const AGENTIC_AUTOFIX_ERROR_EVENT_NAME = 'code-scanning-alert-agentic-autofix-error'

export function dispatchAgenticAutofixError(error: AgenticAutofixError) {
  ssrSafeDocument?.dispatchEvent(new CustomEvent(AGENTIC_AUTOFIX_ERROR_EVENT_NAME, {detail: error}))
}

export function onAgenticAutofixError(callback: (error: AgenticAutofixError) => void) {
  const handler = (event: Event) => callback((event as AgenticAutofixErrorEvent).detail)
  ssrSafeDocument?.addEventListener(AGENTIC_AUTOFIX_ERROR_EVENT_NAME, handler)
  return () => ssrSafeDocument?.removeEventListener(AGENTIC_AUTOFIX_ERROR_EVENT_NAME, handler)
}
