import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

export type UpdateAlertTrackingLinksRequest = {
  issueId: number
}

export type UpdateAlertTrackingLinksResponse = {}

export function useUpdateAlertTrackingLinksMutation<TContext = unknown>(
  path: string,
): UseMutationResult<UpdateAlertTrackingLinksResponse | null, Error, UpdateAlertTrackingLinksRequest, TContext> {
  return useMutation({
    mutationFn: async request => {
      const response = await reactFetchJSON(path, {
        method: 'PATCH',
        body: {
          issue_id: request.issueId,
        },
      })
      if (!response.ok) {
        throw new Error(`${response.status} on ${response.url}`)
      }
      return response.json()
    },
  })
}
