import {useMemo, useRef, useState} from 'react'
import {ActionList, CounterLabel, Dialog, Label, Link, RelativeTime} from '@primer/react'
import {ShieldCheckIcon, ShieldIcon, ShieldXIcon} from '@primer/octicons-react'
import {parseISO} from 'date-fns/parseISO'
import {number as formatNumber} from '@github-ui/formatters'
import type {AffectedBranch} from '../types/affected-branch'
import type {Repository} from '../types/repository'
import type {AffectedBranchConfig} from '../types/affected-branch-config'
import {DeleteConfigurationDialog} from './DeleteConfigurationDialog'

export type AffectedBranchItemProps = {
  affectedBranch: AffectedBranch
  repository: Repository
  canWriteAlert: boolean
  staleAlertsDocsUrl: string
}

export function AffectedBranchItem({
  affectedBranch,
  repository,
  canWriteAlert,
  staleAlertsDocsUrl,
}: AffectedBranchItemProps) {
  const itemRef = useRef<HTMLButtonElement>(null)
  const [isDeleteConfigurationDialogOpen, setIsDeleteConfigurationDialogOpen] = useState(false)

  const state = useMemo(() => {
    if (affectedBranch.dismissed) {
      return 'dismissed' as const
    }

    const allFixed = affectedBranch.configs.every(config => !!config.fixedAt)

    if (allFixed) {
      return 'fixed' as const
    }

    return 'open' as const
  }, [affectedBranch])

  const description = useMemo(() => {
    if (affectedBranch.dismissed) {
      return null
    }

    const allFixed = affectedBranch.configs.every(config => !!config.fixedAt)

    if (!allFixed) {
      const introductionDate = affectedBranch.configs.reduce<Date | null>((earliest, config) => {
        const configDate = parseISO(config.createdAt)
        return earliest === null || configDate < earliest ? configDate : earliest
      }, null)

      return (
        <>
          {affectedBranch.linkedPullRequest && (
            <>Merging pull request #{affectedBranch.linkedPullRequest.number} may fix the alert in this branch. </>
          )}
          {introductionDate && (
            <>
              First detected <RelativeTime date={introductionDate} />
              {affectedBranch.linkedPullRequest && <>.</>}
            </>
          )}
        </>
      )
    }

    const lastFixedConfig = affectedBranch.configs.reduce(
      (latest, config) => {
        const lastConfigDate = latest ? parseISO(latest.fixedAt ?? '') : new Date(0)
        const configFixedAtDate = parseISO(config.fixedAt ?? '')
        return configFixedAtDate > lastConfigDate ? config : latest
      },
      null as AffectedBranchConfig | null,
    )

    if (!lastFixedConfig?.fixedAt) {
      return null
    }

    let fixLocationText: string | null = null
    if (lastFixedConfig.fixCommit) {
      if (lastFixedConfig.fixCommit.isMergeCommit && lastFixedConfig.fixCommit.pullRequest) {
        fixLocationText = `via pull request #${lastFixedConfig.fixCommit.pullRequest.number}`
      } else {
        fixLocationText = `via commit ${lastFixedConfig.fixCommit.shortOid}`
      }
    }

    return (
      <>
        Fixed <RelativeTime date={parseISO(lastFixedConfig.fixedAt)} />
        {fixLocationText && <> {fixLocationText}</>}
      </>
    )
  }, [affectedBranch])

  const showDefaultBranchEmptyStateDialog = affectedBranch.isDefaultBranch && affectedBranch.configs.length === 0

  return (
    <>
      <ActionList.Item as="button" ref={itemRef} onSelect={() => setIsDeleteConfigurationDialogOpen(true)}>
        <ActionList.LeadingVisual>
          {state === 'dismissed' && (
            <span className="fgColor-closed">
              <ShieldXIcon />
            </span>
          )}
          {state === 'open' && (
            <span className="fgColor-success">
              <ShieldIcon />
            </span>
          )}
          {state === 'fixed' && (
            <span className="fgColor-done">
              <ShieldCheckIcon />
            </span>
          )}
        </ActionList.LeadingVisual>
        <div>
          <span className="branch-name f6">{affectedBranch.name}</span>
          {affectedBranch.isDefaultBranch && (
            <Label variant="secondary" className="ml-1">
              default
            </Label>
          )}
        </div>
        {description && <ActionList.Description variant="block">{description}</ActionList.Description>}
        {affectedBranch.configs.length > 1 && (
          <ActionList.TrailingVisual>
            <CounterLabel>{formatNumber(affectedBranch.configs.length)}</CounterLabel>
          </ActionList.TrailingVisual>
        )}
      </ActionList.Item>
      {isDeleteConfigurationDialogOpen &&
        (showDefaultBranchEmptyStateDialog ? (
          <Dialog
            onClose={() => setIsDeleteConfigurationDialogOpen(false)}
            returnFocusRef={itemRef}
            title={
              <>
                No configurations analyzing <strong className="branch-name">{affectedBranch.name}</strong>
              </>
            }
            width="large"
            footerButtons={[
              {
                buttonType: 'default',
                content: 'Close',
                onClick: () => setIsDeleteConfigurationDialogOpen(false),
              },
            ]}
          >
            All configurations for the default branch have been deleted. If this was done by mistake, learn how to fix
            it by{' '}
            <Link inline href={staleAlertsDocsUrl}>
              rerunning a code scan analysis to restore all alerts
            </Link>
            .
          </Dialog>
        ) : (
          <DeleteConfigurationDialog
            onClose={() => setIsDeleteConfigurationDialogOpen(false)}
            onSuccess={() => window.location.reload()}
            affectedBranch={affectedBranch}
            repository={repository}
            returnFocusRef={itemRef}
            canWriteAlert={canWriteAlert}
            staleAlertsDocsUrl={staleAlertsDocsUrl}
          />
        ))}
    </>
  )
}
