import {ActionList, RelativeTime, Truncate} from '@primer/react'
import {parseISO} from 'date-fns/parseISO'
import {campaignRepoPath} from '@github-ui/paths'
import type {Repository} from '../types/repository'
import type {SecurityCampaign} from '../types/security-campaign'

export type SecurityCampaignItemProps = {
  securityCampaign: SecurityCampaign
  repository: Repository
}

export function SecurityCampaignItem({securityCampaign, repository}: SecurityCampaignItemProps) {
  const endsAt = parseISO(securityCampaign.endsAt)
  const isOverdue = endsAt < new Date()

  return (
    <ActionList.LinkItem
      href={campaignRepoPath({
        owner: repository.ownerLogin,
        repo: repository.name,
        campaignNumber: securityCampaign.number,
      })}
      className="d-flex flex-items-center flex-justify-between"
    >
      <Truncate title={securityCampaign.name} className="text-normal" maxWidth="100%">
        {securityCampaign.name}
      </Truncate>
      <ActionList.Description variant="block">
        {`${Math.round(securityCampaign.percentageComplete)}% complete, ${isOverdue ? 'overdue' : 'due'} `}
        <RelativeTime date={endsAt} prefix="" />
      </ActionList.Description>
    </ActionList.LinkItem>
  )
}
