import {AlertMetadata} from '@github-ui/platform-patterns/AlertPageSidebar'
import {ActionList, ActionMenu} from '@primer/react'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'
import {
  TrackingSystem,
  type TrackingIssue,
  type TrackingLink,
} from '@github-ui/code-scanning-shared/types/tracking-link'
import type {TrackingSectionRepository} from './types'
import {IssueItem} from '@github-ui/issue-metadata/IssueItem'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {IssueState, IssueStateReason, IssuePickerItem} from '@github-ui/item-picker/IssuePicker'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {RelayEnvironmentProvider, relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {CreateIssueDialogEntry} from '@github-ui/issue-create/CreateIssueDialogEntry'
import {noop} from '@github-ui/noop'
import {useUpdateAlertTrackingLinksMutation} from './hooks/use-update-alert-tracking-links-mutation'
import {codeScanningAlertTrackingLinksPath} from '@github-ui/paths'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {type PickerType, RepositoryAndIssuePicker} from '@github-ui/item-picker/RepositoryAndIssuePicker'
import {SavingSpinner} from '@github-ui/code-scanning-shared/components/SavingSpinner'
import {InlineMessage} from '@primer/react/experimental'
import {dispatchTrackingIssueChanged} from './tracking-issue-event'

async function refreshTrackingIssuePill() {
  // Only run in browser environment
  if (typeof window === 'undefined') return

  // updateContent requires the data-url attribute to be present
  const trackingIssuePillElement = document.querySelector<HTMLElement>('.alert-tracking-link-pill[data-url]')
  if (!trackingIssuePillElement) return

  // Dynamic import to avoid SSR issues - the module may reference `window` at initialization
  // This avoids a "ReferenceError: window is not defined" error from the Alloy smoke test
  const {updateContent} = await import('@github-ui/updatable-content')
  await updateContent(trackingIssuePillElement)
}

export interface CodeScanningTrackingSectionProps {
  alertTrackingLinks: TrackingLink[]
  alertNumber: number
  repository: TrackingSectionRepository
  readonly: boolean
}

export function CodeScanningTrackingSection({
  alertTrackingLinks,
  alertNumber,
  repository,
  readonly,
}: CodeScanningTrackingSectionProps) {
  const environment = useMemo(() => relayEnvironmentWithMissingFieldHandlerForNode(), [])

  const [menuOpen, setMenuOpen] = useState(false)
  const [pickerType, setPickerType] = useState<PickerType>(null)
  const [alertTrackingLinksState, setAlertTrackingLinksState] = useState<TrackingLink[]>(alertTrackingLinks)
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false)

  const trackingIssue = alertTrackingLinksState.find(link => link.issue)?.issue

  const sectionHeaderRef = useRef<HTMLButtonElement | null>(null)

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setAlertTrackingLinksState(alertTrackingLinks)
  }, [alertTrackingLinks])

  const onPickerTypeChange = useCallback((type: PickerType) => {
    setPickerType(type)
  }, [])

  const {
    mutate: mutateUpdateTrackingLinks,
    isPending,
    error: mutationError,
  } = useUpdateAlertTrackingLinksMutation(
    codeScanningAlertTrackingLinksPath({owner: repository.ownerLogin, repo: repository.name, alertNumber}),
  )

  const onTrackingIssueSelection = useCallback(
    (selectedIssues: IssuePickerItem[]) => {
      const selectedIssue = selectedIssues[0] || null

      const filteredLinks = alertTrackingLinksState.filter(link => link.trackingSystem !== TrackingSystem.GITHUB_ISSUE)

      const [ownerLogin = '', name = ''] = selectedIssue?.repository.nameWithOwner.split('/') ?? []

      const selectedTrackingIssue: TrackingIssue | null = selectedIssue
        ? {
            id: selectedIssue.databaseId ?? 0,
            nodeId: selectedIssue.id,
            number: selectedIssue.number,
            repository: {
              ownerLogin,
              name,
              typeIcon: '',
              defaultBranch: '',
            },
            state: selectedIssue.state,
            stateReason: selectedIssue.stateReason || null,
            title: selectedIssue.title,
            titleHTML: '',
            url: selectedIssue.url,
          }
        : null

      mutateUpdateTrackingLinks(
        {
          issueId: selectedIssue?.databaseId ?? 0,
        },
        {
          onSuccess: () => {
            setPickerType(null)
            setAlertTrackingLinksState(
              selectedTrackingIssue
                ? [
                    ...filteredLinks,
                    {trackingSystem: TrackingSystem.GITHUB_ISSUE, issue: selectedTrackingIssue, trackingUrl: null},
                  ]
                : filteredLinks,
            )
            refreshTrackingIssuePill()
            dispatchTrackingIssueChanged(selectedTrackingIssue)
          },
          onError: () => {
            setPickerType(null)
          },
        },
      )
    },
    [mutateUpdateTrackingLinks, alertTrackingLinksState],
  )

  const handleAddTrackingIssue = useCallback(() => {
    setMenuOpen(false)
    setPickerType('Issue')
  }, [])

  const anchorElement = useCallback(
    (props: unknown) => {
      const {ref} = props as {
        ref: React.RefObject<HTMLButtonElement | null>
      }
      if (ref) {
        ref.current = sectionHeaderRef.current
      }
      return <></>
    },
    [sectionHeaderRef],
  )

  const handleSectionHeaderClick = useCallback(() => {
    setPickerType(null)
    setMenuOpen(o => !o)
  }, [])

  const handleCreateIssue = (issue: TrackingIssue) => {
    const filteredLinks = alertTrackingLinksState.filter(link => link.trackingSystem !== TrackingSystem.GITHUB_ISSUE)

    mutateUpdateTrackingLinks(
      {issueId: issue.id},
      {
        onSuccess: () => {
          setIsCreateDialogOpen(false)
          setAlertTrackingLinksState([
            ...filteredLinks,
            {trackingSystem: TrackingSystem.GITHUB_ISSUE, issue, trackingUrl: null},
          ])
          refreshTrackingIssuePill()
          dispatchTrackingIssueChanged(issue)
        },
        onError: () => {
          setIsCreateDialogOpen(false)
        },
      },
    )
  }

  // The controller returns issue state and reason in lowercase, but the IssueItem component expects uppercase values
  const getIssueStateAndStateReason = (issue: TrackingIssue) => {
    const state = issue.state.toUpperCase() as IssueState
    const stateReason = issue.stateReason ? (issue.stateReason.toUpperCase() as IssueStateReason) : undefined

    // The IssueItem component requires a stateReason but the controller returns an empty reason
    if (state === 'CLOSED' && !stateReason) {
      return {state: 'CLOSED' as IssueState, stateReason: 'COMPLETED' as IssueStateReason}
    }

    return {state, stateReason}
  }

  const renderTrackingLink = (trackingLink: TrackingLink) => {
    if (trackingLink.trackingSystem === TrackingSystem.GITHUB_ISSUE && trackingLink.issue) {
      const {state, stateReason} = getIssueStateAndStateReason(trackingLink.issue)

      return (
        <ActionList variant="full" key={trackingLink.issue.id}>
          <IssueItem
            issue={{
              ...trackingLink.issue,
              id: trackingLink.issue.id.toString(),
              state,
              stateReason,
              repository: {
                nameWithOwner: `${trackingLink.issue.repository.ownerLogin}/${trackingLink.issue.repository.name}`,
              },
            }}
          />
        </ActionList>
      )
    }

    return null
  }

  const alertMetadataProps = readonly
    ? {}
    : {
        buttonRef: sectionHeaderRef,
        buttonProps: {onClick: handleSectionHeaderClick},
      }

  return (
    <RelayEnvironmentProvider environment={environment}>
      <AlertMetadata title="Tracking" {...alertMetadataProps}>
        {!readonly && (
          <>
            <RepositoryAndIssuePicker
              onPickerTypeChange={onPickerTypeChange}
              selectedIssueIds={trackingIssue ? [trackingIssue.nodeId] : []}
              onIssueSelection={onTrackingIssueSelection}
              organization={repository.ownerLogin}
              defaultRepositoryNameWithOwner={`${repository.ownerLogin}/${repository.name}`}
              pickerType={pickerType}
              anchorElement={anchorElement}
            />

            <ActionMenu open={menuOpen} onOpenChange={setMenuOpen} anchorRef={sectionHeaderRef}>
              <ActionMenu.Overlay width="medium">
                <ActionList>
                  <ActionList.Item onSelect={() => setIsCreateDialogOpen(true)}>Create issue</ActionList.Item>
                  <ActionList.Item onSelect={handleAddTrackingIssue}>
                    {trackingIssue ? 'Change or remove issue' : 'Add existing GitHub issue'}
                  </ActionList.Item>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </>
        )}

        <SavingSpinner isSaving={isPending} />

        {alertTrackingLinksState.length > 0 && alertTrackingLinksState.map(renderTrackingLink)}

        {alertTrackingLinksState.length === 0 && <span>Link an issue to this alert.</span>}

        {mutationError && (
          <InlineMessage variant="critical" size="small" className="pb-2">
            Unable to save your selection due to server error. Try a moment later.
          </InlineMessage>
        )}

        {isCreateDialogOpen && (
          <CreateIssueDialogEntry
            navigate={noop}
            isCreateDialogOpen={isCreateDialogOpen}
            setIsCreateDialogOpen={setIsCreateDialogOpen}
            optionConfig={{
              scopedOrganization: repository.ownerLogin,
              issueCreateArguments: {
                repository: {
                  owner: repository.ownerLogin,
                  name: repository.name,
                },
              },
              hideCreateMore: true,
            }}
            onCreateSuccess={props => {
              if (props.issue.databaseId == null) {
                return
              }

              handleCreateIssue({
                id: props.issue.databaseId,
                nodeId: props.issue.id,
                number: props.issue.number,
                repository: {
                  name: props.issue.repository.name,
                  ownerLogin: props.issue.repository.owner.login,
                  typeIcon: '',
                  defaultBranch: '',
                },
                state: 'open',
                stateReason: null,
                title: props.issue.title,
                titleHTML: props.issue.title,
                url: props.issue.url,
              })
            }}
          />
        )}
      </AlertMetadata>
    </RelayEnvironmentProvider>
  )
}
