import {ActionList, RelativeTime, Text} from '@primer/react'
import {GitBranchIcon} from '@primer/octicons-react'
import type {BranchData} from '../types'

type BranchItemProps = {
  branch: BranchData
}

export function BranchItem({branch: {name, url, lastModifiedAt}}: BranchItemProps) {
  return (
    <ActionList.LinkItem href={url} target="_blank" data-testid="development-section-branch-item">
      <ActionList.LeadingVisual>
        <GitBranchIcon />
      </ActionList.LeadingVisual>

      <Text weight="normal">{name}</Text>

      <ActionList.Description variant="block">
        <span data-testid="development-section-branch-description">
          Updated <RelativeTime datetime={lastModifiedAt} tense="past" />
        </span>
      </ActionList.Description>
    </ActionList.LinkItem>
  )
}
